import React from 'react';
import { IterationData } from '../../types';

interface IterationTableProps {
    history: IterationData[];
    solution: number[];
}

export const IterationTable: React.FC<IterationTableProps> = ({ history }) => {

    // Единая функция форматирования для таблицы
    const formatValue = (value: number, isError: boolean = false): string => {
        if (value === 0) return "0.0";

        if (isError) {
            // Для погрешностей убираем экспоненту и показываем до 12 знаков
            return value.toFixed(12).replace(/\.?0+$/, '');
        }

        // Для обычных значений x[i]
        return value.toLocaleString('ru-RU', {
            minimumFractionDigits: 1,
            maximumFractionDigits: 10,
            useGrouping: false
        }).replace(',', '.');
    };

    return (
        <div className="overflow-x-auto border border-slate-200 rounded-lg">
            <table className="min-w-full divide-y divide-slate-200 text-sm font-mono">
                <thead className="bg-slate-50 text-[10px] font-bold uppercase text-slate-500">
                <tr>
                    <th className="px-4 py-2 text-left border-r">№</th>
                    {history[0]?.values.map((_, idx) => (
                        <th key={idx} className="px-4 py-2 text-right">x{idx + 1}</th>
                    ))}
                    <th className="px-4 py-2 text-right border-l text-slate-900">max |Δ|</th>
                </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 bg-white">
                {history.map((row, index) => (
                    <tr key={index} className="hover:bg-slate-50 transition-colors">
                        <td className="px-4 py-1.5 border-r text-slate-400 text-xs">
                            {index}
                        </td>
                        {row.values.map((val, idx) => (
                            <td key={idx} className="px-4 py-1.5 text-right whitespace-nowrap">
                                {formatValue(val)}
                            </td>
                        ))}
                        <td className="px-4 py-1.5 text-right border-l font-bold text-slate-700 bg-slate-50/50">
                            {formatValue(row.maxError, true)}
                        </td>
                    </tr>
                ))}
                </tbody>
            </table>
        </div>
    );
};
